import{c as e,Q as d,j as a,m as r}from"./chunks/framework.DOi4mjdC.js";const p=JSON.parse('{"title":"毕昇编译器简介","description":"","frontmatter":{},"headers":[{"level":1,"title":"毕昇编译器简介","slug":"毕昇编译器简介"}],"relativePath":"guide/编程指南/编译与运行/算子编译/毕昇编译器.md","filePath":"guide/编程指南/编译与运行/算子编译/毕昇编译器.md"}'),l={name:"guide/编程指南/编译与运行/算子编译/毕昇编译器.md"};function i(s,t,o,n,c,h){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="毕昇编译器简介" tabindex="-1">毕昇编译器简介 <a class="header-anchor" href="#毕昇编译器简介" aria-label="Permalink to &quot;毕昇编译器简介&quot;">​</a></h1><p>毕昇编译器是专为昇腾AI处理器设计的异构编译器，原生支持Ascend C算子代码的编译，可将用户编写的算子程序高效转换为二进制可执行文件或动态库。编译器的可执行文件名为bisheng，支持x86、aarch64等多种主机平台，并直接提供对设备侧AI Core架构的指令集编译支持。借助毕昇编译器，开发者可以更高效、便捷地完成面向昇腾平台的算子开发与优化工作。</p><p>目前，编译器支持如下型号：</p><ul><li>Ascend 950PR/Ascend 950DT</li><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品</li><li>Atlas 推理系列产品</li></ul><p>毕昇编译器支持的源码文件核头文件如下：</p><table tabindex="0"><thead><tr><th>文件扩展名</th><th>描述</th><th>内容</th></tr></thead><tbody><tr><td>.c</td><td>C源码文件</td><td>Host-only代码</td></tr><tr><td>.cpp, .cc, .cxx</td><td>C++源码文件</td><td>Host-only代码</td></tr><tr><td>.h, .hpp, .hh, .hxx</td><td>C/C++ 头文件</td><td>Device代码， Host代码， Host/Device混合代码</td></tr><tr><td>.asc</td><td>Ascend C源码文件</td><td>Device代码， Host代码， Host/Device混合代码</td></tr></tbody></table><ul><li>异构编译场景中的编程相关约束请参考<a href="./约束说明.html">约束说明</a>。</li><li>如果需要了解更多的毕昇编译器的基础知识，详细内容请参考<a href="https://www.hiascend.com/document/redirect/CannCommunityBiSheng" target="_blank" rel="noreferrer">《毕昇编译器用户指南》</a>。</li></ul>',7)])])}const A=e(l,[["render",i]]);export{p as __pageData,A as default};
